// Some portions generated by Codex
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const { createFormBrowserHarness } = require('./form-browser-harness.js');
const { installDetailDisclosureTemplateRuntime } = require('./workbench-detail-disclosure-runtime.js');

const scripts = require('./workbench-scripts.js').compiledScriptsDir();

for (const [stage, error] of [
    ['load', null],
    ['validation failure', 'The repository ID must remain unchanged.'],
    ['initialization failure', 'The configuration was saved, but the repository could not initialize.']
]) {
    test('configuration model prepares the editor row after ' + stage, async () => {
        const workbench = {};
        installDetailDisclosureTemplateRuntime(workbench);
        const context = vm.createContext({ console, workbench, window: {}, URL, URLSearchParams, Promise,
            TextDecoder, TextEncoder, setTimeout, clearTimeout, performance });
        for (const script of ['queryStream.js', 'workbenchViews.js', 'workbenchApp.js']) {
            vm.runInContext(fs.readFileSync(path.join(scripts, script), 'utf8'), context);
        }
        const turtle = '@prefix config: <tag:rdf4j.org,2023:config/> . [] a config:Repository .';
        const rows = [[{ kind: 'literal', value: turtle }, error ? { kind: 'literal', value: error } : null]];
        const records = [
            { type: 'head', version: 1 }, { type: 'view', id: 'config' },
            { type: 'vars', values: ['configuration', 'error-message'] },
            { type: 'rows', values: rows }, { type: 'end' }
        ];
        const response = new Response(records.map((record) => JSON.stringify(record)).join('\n') + '\n', {
            status: error ? 400 : 200,
            headers: { 'Content-Type': 'application/vnd.rdf4j.workbench+ndjson; charset=UTF-8' }
        });
        const model = await context.workbench.app.loadModelFromResponse(response);
        try {
            await context.workbench.app.prepareInitialRows(model);

            assert.deepEqual(JSON.parse(JSON.stringify(model.rows)), rows,
                'load the real parser/row-store configuration row into the form renderer');
            const runtime = { nothing: '', html: (strings, ...values) => ({ strings: Array.from(strings), values }), render() {} };
            const rendered = context.workbench.views.pageTemplate(model,
                { basePath: '/workbench', repositoryId: 'repo', workbench: { menu: [] } }, runtime);
            const markup = flat(rendered);
            assert.ok(markup.includes(turtle), 'the Turtle is in the rendered editor');
            if (error) { assert.ok(markup.includes(error), 'the retained error is beside the editor'); }
        } finally {
            await model.rowStore.dispose();
        }
    });
}

test('repository configuration has a router lifecycle and loads its editor', () => {
    const context = vm.createContext({ workbench: {} });
    vm.runInContext(fs.readFileSync(path.join(scripts, 'workbenchRoutes.js'), 'utf8'), context);
    const route = context.workbench.routes.get('config');
    assert.ok(route);
    assert.equal(route.routerReady, true);
    assert.equal(route.keepAlive, false);
    assert.ok(Array.from(route.baseScripts()).includes('configuration.js'));
});

test('configuration editor submits its current text and releases its listeners', () => {
    const harness = createFormBrowserHarness();
    const page = harness.registerElement('div', { id: 'config-page' });
    const textarea = harness.registerElement('textarea', { id: 'configuration', value: 'persisted configuration' });
    textarea.defaultValue = textarea.value;
    page.appendChild(textarea);
    harness.document.body.appendChild(page);
    const calls = [];
    let value = textarea.value;
    let changed;
    harness.context.CodeMirror = {
        fromTextArea(element, options) {
            assert.equal(element, textarea);
            assert.equal(options.lineNumbers, true);
            return {
                getValue: () => value,
                setSize() {},
                refresh() {},
                save() { textarea.value = value; calls.push('save'); },
                on(name, listener) { assert.equal(name, 'change'); changed = listener; },
                off(name, listener) { assert.equal(name, 'change'); assert.equal(listener, changed); calls.push('off'); },
                toTextArea() { calls.push('closed'); }
            };
        }
    };
    harness.loadScripts(['configuration.js']);
    const dispose = harness.context.workbench.configuration.mount(page);
    value = 'edited nested configuration';
    changed();
    assert.equal(textarea.value, value, 'CodeMirror changes keep the native form current');
    harness.context.workbench.configuration.save();
    assert.equal(textarea.value, value);
    dispose();
    dispose();
    assert.deepEqual(calls, ['save', 'save', 'off', 'closed']);
});

test('a newly mounted editor uses the rendered configuration instead of a dirty reused textarea value', () => {
    const harness = createFormBrowserHarness();
    const page = harness.registerElement('div');
    const textarea = harness.registerElement('textarea', { id: 'configuration', value: 'rejected old draft' });
    textarea.defaultValue = 'fresh saved configuration';
    page.appendChild(textarea);
    harness.document.body.appendChild(page);
    harness.context.CodeMirror = {
        fromTextArea(element) {
            assert.equal(element.value, 'fresh saved configuration');
            return { on() {}, off() {}, refresh() {}, toTextArea() {} };
        }
    };
    harness.loadScripts(['configuration.js']);

    const dispose = harness.context.workbench.configuration.mount(page);

    dispose();
});

function configurationPage() {
    const workbench = {};
    installDetailDisclosureTemplateRuntime(workbench);
    const context = vm.createContext({ console, URL, URLSearchParams, Promise, workbench, window: {}, setTimeout });
    vm.runInContext(fs.readFileSync(path.join(scripts, 'workbenchViews.js'), 'utf8'), context);
    const model = { viewId: 'config', vars: ['configuration', 'error-message'],
        rows: [[{ kind: 'literal', value: 'typed Turtle configuration' }, null]], rowCount: 1, metadata: {} };
    const runtime = { nothing: '', html: (strings, ...values) => ({ strings: Array.from(strings), values }), render() {} };
    const view = { basePath: '/workbench', repositoryId: 'repo', workbench: { menu: [] } };
    return { context, model, template: context.workbench.views.pageTemplate(model, view, runtime) };
}

function handlers(template, result = []) {
    if (Array.isArray(template)) { template.forEach((part) => handlers(part, result)); }
    if (template && template.strings) {
        template.values.forEach((value, index) => {
            if (typeof value === 'function') {
                result.push({ before: template.strings[index], value });
            } else { handlers(value, result); }
        });
    }
    return result;
}

function flat(template) {
    if (Array.isArray(template)) { return template.map(flat).join(''); }
    if (template && template.strings) {
        return template.strings.map((part, index) => part
            + (index < template.values.length ? flat(template.values[index]) : '')).join('');
    }
    return template == null || typeof template === 'function' ? '' : String(template);
}

for (const [action, message] of [
    ['save', 'Configuration saved. Restart the repository to apply it.'],
    ['save-and-restart', 'Configuration saved and repository restarted.']
]) {
    test(action + ' sends the current editor text and reports its own confirmed outcome', async () => {
        const { context, model, template } = configurationPage();
        let saved = false;
        context.workbench.configuration = { save() { saved = true; } };
        const button = { value: action };
        context.workbench.router = { send(form, submitter) {
            assert.equal(saved, true, 'save the editor before the form is serialized');
            assert.equal(submitter, button, 'the requested lifecycle action is preserved');
            return Promise.resolve('done');
        } };
        const submit = handlers(template).find((entry) => /@submit=$/.test(entry.before)).value;
        submit({ preventDefault() {}, submitter: button,
            currentTarget: { isConnected: true, closest: () => null } });
        await new Promise(setImmediate);
        assert.equal(model.submission.state, 'done');
        assert.equal(model.submission.message, message);
    });
}

test('a failed restart preserves the server stage instead of showing applied success', async () => {
    const { context, model, template } = configurationPage();
    context.workbench.configuration = { save() {} };
    const failure = 'Configuration was saved, but the repository could not initialize.';
    context.workbench.router = { send(form, button, failed) {
        failed({ status: 500, message: failure });
        return Promise.resolve('failed');
    } };
    const submit = handlers(template).find((entry) => /@submit=$/.test(entry.before)).value;
    submit({ preventDefault() {}, submitter: { value: 'save-and-restart' },
        currentTarget: { isConnected: true, closest: () => null } });
    await new Promise(setImmediate);
    assert.equal(model.submission.state, 'failed');
    assert.equal(model.submission.message, failure);
    assert.equal(model.rows[0][0].value, 'typed Turtle configuration');
});
